import {uiQuery} from './router.js';
import {personalRisk,evaluateTracking,trackingCourses} from './tracking-core.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=v=>v.toLocaleString('tr-TR');
const reasons={assignment_coverage:'Ödev kapsamı tam doğrulanmadı',session_coverage:'Gerçekleşmiş oturum kapsamı eksik',source_stale:'Kaynak kontrolü eski / erişilemiyor',personal_source:'Kişisel ders · Ninova kimliği bekliyor',assignment_identity:'Ödev kimliği eşleşmesi eksik',assignment_date:'Ödev tarihi bilinmiyor',assignment_stale:'İlgili ödev kontrolü bekliyor',group_unknown:'Grup teslimi / kapsamı belirsiz',upload_unknown:'Yükleme sayısı bilinmiyor',attendance_unknown:'Geçmiş yoklama belirsiz',session_status:'Oturumun gerçekleşme durumu belirsiz',starting:'Henüz yeterli gerçekleşmiş kayıt yok'};
let school,attendance=window.keplerAttendanceOverview||{state:'loading',items:[]},snapshot=window.keplerAssignmentSnapshot||null;
function model(){return trackingCourses(school.courses,attendance.courses||[]).map(course=>{const summary=attendance.items?.find(i=>i.courseId===course.id),risk=personalRisk(summary,attendance.state),assignments=(snapshot?.records||[]).filter(r=>r.courseId===course.id),coverage=snapshot?.coverageByCourse?.[course.id],proof=attendance.sessionCoverageByCourse?.[course.id];
 // Published prose coverage is not a machine-readable completeness certificate.
 const tier=evaluateTracking({courseId:course.id,personalOnly:course.personalOnly,assignments,assignmentCoverage:coverage?.complete===true,records:attendance.records||[],sessions:attendance.sessions||[],sessionsCoverage:proof?.complete===true,sourceAt:snapshot?.checkedAt,staleAfterHours:school.staleAfterHours});
 const detail=course.personalOnly?'Kişisel ders · kaynak kimliği bekleniyor':assignments.some(a=>a.scope!=='individual')?'Grup / kapsam doğrulaması bekliyor':summary?.unknown?`${summary.unknown} geçmiş gün belirsiz`:assignments.some(a=>!a.id.startsWith('ninova-')||!a.dueAt)?'Ödev kimliği / tarih eksiği':'Takip kapsamı doğrulanmalı';return {course,summary,risk,tier,detail};});}
const riskBadge=r=>`<span class="tracking-risk risk-${r.tone}"><b aria-hidden="true">${r.icon}</b>${esc(r.label)}</span>`;
function render(){if(!school)return;const items=model(),home=uiQuery('#courseTracking'),diagram=uiQuery('#attendanceDiagram');
 if(home)home.innerHTML=`<div class="tracking-heading"><div><p class="workspace-kicker">TEK BAKIŞTA · ${items.length} DERS</p><h2 id="trackingTitle">Derslerimin takibi</h2></div><a href="#/attendance">Yoklama pusulam →</a></div><p class="tracking-caption">Takip tier’i · resmî not veya başarı tahmini değildir. Bilgi eksikse ceza ya da otomatik AA üretmez.</p><div class="tracking-grid">${items.map(({course:c,summary:s,risk,tier,detail})=>`<article class="tracking-card risk-${risk.tone}" data-tracking-course="${esc(c.id)}"><div class="tracking-card-top"><a href="${c.personalOnly?'#/attendance':'#/courses/'+encodeURIComponent(c.id)+'/overview'}" ${c.personalOnly?'data-attendance-course="'+esc(c.id)+'"':''}>${esc(c.id)} <span aria-hidden="true">↗</span></a><span class="tracking-tier" aria-label="${esc(tier.tier?'Takip tieri '+tier.tier:'Doğrulama bekliyor')}">${esc(tier.tier||'?')}</span></div><h3>${esc(c.nameTr||c.name||c.id)}</h3><p class="tracking-state">${tier.status==='ready'?'Takip kaydı hazır':tier.status==='starting'?'Başlangıç':'Doğrulama bekliyor'}</p>${riskBadge(risk)}<details><summary>Neden?</summary><p>${esc(detail)}</p><ul>${tier.reasons.map(r=>`<li>${esc(reasons[r]||r)}</li>`).join('')}</ul>${s?`<p>${s.recordCount} kişisel kayıt · ${s.unknown} belirsiz gün. Katılım resmî doğrulama değildir.</p>`:''}</details></article>`).join('')}</div>`;
 if(diagram)diagram.innerHTML=`<div class="tracking-heading"><div><p class="workspace-kicker">KİŞİSEL KAYITLARIN · ${items.length} DERS</p><h2 id="diagramTitle">Yoklama pusulam</h2></div><a class="diagram-primary" href="#/calendar">Katılımını işaretle ↗</a></div><p class="tracking-caption">Çubuk: kullanılan kişisel hak / kişisel limit. Yarım = 0,5; belirsiz günler devamsız sayılmaz.</p><div class="attendance-compass" role="list">${items.map(({course:c,summary:s,risk})=>`<article role="listitem" class="compass-row risk-${risk.tone}" data-compass-course="${esc(c.id)}"><div class="compass-name"><strong>${esc(c.id)}</strong><span>${c.personalOnly?'Kişisel tracker · kaynak bekleniyor':esc(c.nameTr||c.name)}</span></div><div class="compass-metric"><div class="compass-bar ${risk.fraction===null?'unknown-budget':''}" role="img" aria-label="${esc(risk.fraction===null?'Kullanım veya kişisel limit bilinmiyor':`${num(s.used)} kullanılan / ${num(s.limit)} kişisel limit; ${risk.label}`)}"><span style="width:${risk.fraction===null?0:Math.round(risk.fraction*100)}%"></span></div><small>${risk.fraction===null?'Kayıt / limit okununca gösterilecek':`${num(s.used)} / ${num(s.limit)} oturum`}${s?.unknown?' · '+s.unknown+' gün belirsiz':''}</small></div>${riskBadge(risk)}</article>`).join('')}</div><details class="tracking-evidence"><summary>Hesap ve kaynak kapsamı</summary><p>Yalnız kendi kayıtların ve kişisel limitlerin. Boş günler yok sayılmaz; gelecekteki dersler kullanıma eklenmez. ${attendance.updatedAt?'Son yerel kayıt: '+esc(new Intl.DateTimeFormat('tr-TR',{timeZone:'Europe/Istanbul',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(attendance.updatedAt)))+' İstanbul.':'Güncel kayıt zamanı okunamadı.'}</p></details>`;
}
export function initTracking(data){school=data;attendance=window.keplerAttendanceOverview||attendance;snapshot=window.keplerAssignmentSnapshot||snapshot;document.addEventListener('kepler:attendance-overview',e=>{attendance=e.detail;render()});document.addEventListener('kepler:assignment-snapshot',e=>{snapshot=e.detail.state==='ready'?e.detail.snapshot:null;render()});document.addEventListener('kepler:progress-rendered',render);render();}
